@module sonority  src=sonority.lua  loc=254  mode=namespace  self=sonority

# Invariants & contracts
  @invariant  pure module: no state, no ratios, no cents — coords/strikes/releases/classes → indices  @ 5

# Shapes
  @shape  Coords = {[oddPrime]=exponent}; prime 2 is absent, so the score reads harmony not spacing  @ 6
  @shape  Strand = { notes={ {ppq,pitch,endppq,..},.. }, class=<step-class>, shortlist={ Candidate,.. } }; the walk reads the strikes, the releases and the class  @ 7
  @shape  Sonority = { ppq, strands={ strandIndex,.. } }; most recently struck first, the last n struck and whatever else still sounds  @ 8
  @shape  Candidate = { coords=Coords, strain=<distance from the written step, in half-windows> }  @ 9

# Imports
  @const util = 'util'  @ 11

# Module-level constants
  @const sonority = {}  @ 12
  @const weights = {}  @ 17
  @const budget = 200000  @ 160

# Private functions
  -- The box
  @fn weight(prime)  @ 18-22
  -- The walk
  @fn strikesInOrder(strands)  @ 50-63
      -- Every strike, in onset order, lowest last — so a released chord leaves its
      -- bass to the sonority that follows (design/adaptive-tuning.md § The model).
  @fn sounding(strand, ppq)  @ 67-72
      -- Half-open, so a note released where the next is struck does not sound there,
      -- and a passage whose notes stop as the next begin reads as the last n struck.
  @fn promote(recent, strands, index)  @ 76-82
      -- The class holds one entry however many notes write it: a restrike moves its
      -- own entry to the front, and a second strand of the class takes the entry over.
  -- The objective
  -- The solve
  @fn schedule(strands, sonorities)  @ 130-156
      -- A strand is live from the onset it is chosen at to the last that reads it, both
      -- known before enumeration (§ Solving it), and listed in strand order for keying.
      @contract  strands, sonorities → per onset the strands born there, live there, and held from before  @ 129
  @fn assertAffordable(strands, plan)  @ 162-172
  @fn placementsAt(strands, born, strength)  @ 176-195
      -- Every combination of the shortlists of the strands born at an onset, with the
      -- pull each charges — the same against every state, so charged once here.
  @fn keyOf(choice, list)  @ 197-201

# Public API (sonority.*)
  @api sonority.score(coordSet)  @ 28-44
      -- The axes are gathered before any is measured: a member holding no exponent on
      -- an axis sits at 0 there, and that 0 is only in the span once the axis is known
      -- to exist — an axis every member names does not reach back to the origin.
      @contract  coords[] → Σ over the odd primes of (highest exponent − lowest) × log₂ p  @ 27
  @api sonority.walk(strands, n)  @ 87-102
      -- The whole onset is absorbed before the sonority is taken, so a chord wider
      -- than n leaves its own lowest notes standing rather than its predecessor's.
      @contract  strands, n → a Sonority per onset: last n distinct classes struck, plus sounding  @ 86
  @api sonority.cost(strands, n, strength, choice)  @ 109-123
      -- The pull is counted once per strand rather than once per note, so an octave
      -- doubling changes no answer: the box already charges it nothing.
      @contract  strands, n, strength, choice → box over the walk + strength × strain² per strand  @ 108
  @api sonority.solve(strands, n, strength)  @ 206-252
      -- The state carries the whole choice vector rather than a backpointer: two
      -- generations are alive at a time and the budget bounds them.
      @contract  strands, n, strength → the index per strand minimising sonority.cost, exactly  @ 205

# Uses (outbound edges)
  @use call    util.add  @ strikesInOrder:54 walk:97,99 cost:114 schedule:149,151,152 placementsAt:185
  @use call    util.clone  @ placementsAt:185 solve:232
  @use call    util.key  @ keyOf:200 solve:215
  @use require util  @ <load>:11

# Calls (intra-file)
  @call assertAffordable  @ solve:213
  @call keyOf  @ solve:221,241
  @call placementsAt  @ solve:230
  @call promote  @ walk:92
  @call schedule  @ solve:212
  @call sonority.score  @ cost:116 solve:240
  @call sonority.walk  @ cost:111 solve:211
  @call sounding  @ walk:97
  @call strikesInOrder  @ walk:88
  @call weight  @ score:41

